INSERT INTO phaladeepika_yoga (yoga_id,yoga_hi,yoga_en,category,ref,yoga_type,rule_text,result_text,language) VALUES
('PMP01','रुचक योग','Ruchaka','पंच महापुरुष योग','6.1-2','shubh','मंगल अपनी राशि (मेष/वृश्चिक) अथवा उच्च राशि (मकर) का होकर केन्द्र (1,4,7,10) में स्थित हो।','दीर्घ चेहरा, बहुत साहसी, धनवान, शूर व बली, शत्रुओं को हराने वाला, अभिमानी, सेनापति (उच्च पदाधिकारी), प्रसिद्ध व कीर्तिमान, प्रत्येक उद्योग में विजयी।','hi'),
('PMP02','भद्र योग','Bhadra','पंच महापुरुष योग','6.1-3','shubh','बुध अपनी राशि (मिथुन/कन्या) का होकर केन्द्र (1,4,7,10) में स्थित हो।','कुशाग्र (तीव्र) बुद्धि, शुद्ध, विद्वानों द्वारा प्रशंसित, भाषण में चतुर, अत्यन्त वैभवशाली, उच्च पदाधिकारी।','hi'),
('PMP03','हंस योग','Hansa','पंच महापुरुष योग','6.1-3','shubh','बृहस्पति कर्क (उच्च) / धनु / मीन (स्वराशि) का होकर केन्द्र (1,4,7,10) में स्थित हो।','हाथ-पैरों में शंख, कमल, मत्स्य व अंकुश के चिह्न, शुभ व सुन्दर शरीर, उत्तम भोजन करने वाला, सज्जन उसकी प्रशंसा करें।','hi'),
('PMP04','मालव्य योग','Malavya','पंच महापुरुष योग','6.1-3','shubh','शुक्र वृष / तुला (स्वराशि) अथवा मीन (उच्च) का होकर केन्द्र (1,4,7,10) में स्थित हो।','वैभवशाली व पुष्ट अंग वाला, उत्तम भोजन, विद्वान, प्रसन्नमुख, शान्तचित्त, पुत्र व स्त्री सुख से युक्त, यशस्वी, सवारियों (वाहन) का भोक्ता।','hi'),
('PMP05','शश योग','Sasha','पंच महापुरुष योग','6.1-4','shubh','शनि तुला (उच्च) / मकर / कुम्भ (स्वराशि) का होकर लग्न से केन्द्र (1,4,7,10) में स्थित हो।','ग्राम/नगर का स्वामी अथवा नृप (उच्च पदाधिकारी), स्वयं बलवान, अधीनस्थ अच्छे लोग, अन्य लोग प्रशंसा करें; किन्तु आचरण उत्तम नहीं, अन्य स्त्रियों में आसक्त, धनी व सुखी।','hi'),
('PMP-BHANGA','महापुरुष भंग','Mahapurusha Bhanga','पंच महापुरुष योग','6.4 (मानसागरी)','ashubh','मंगल/बुध/बृहस्पति/शुक्र/शनि उच्च या स्वराशि में केन्द्र में हो किन्तु सूर्य या चन्द्रमा के साथ हो तो महापुरुष योग भंग होता है।','राजा (राजतुल्य) नहीं बनता, किन्तु उसकी दशा/अन्तर्दशा में केवल सत्फल (शुभ फल) प्राप्त होता है।','hi'),
('CH01','सुनफा योग','Sunapha','चन्द्र योग','6.5-7','shubh','चन्द्रमा से द्वितीय भाव में कोई ग्रह (सूर्य को छोड़कर) हो और द्वादश में कोई ग्रह न हो।','स्वयं अर्जित धन वाला, राजा या राजतुल्य, बुद्धिमान, धनवान व ख्याति प्राप्त।','hi'),
('CH02','अनफा योग','Anapha','चन्द्र योग','6.6-7','shubh','चन्द्रमा से द्वादश भाव में कोई ग्रह (सूर्य को छोड़कर) हो और द्वितीय में कोई ग्रह न हो।','देखने में उत्तम, शीलवान, सांसारिक भोग-साधन सम्पन्न, सन्तोषी, प्रसन्न, उत्तम वस्त्रधारी, स्वस्थ शरीर, समाज में प्रतिष्ठित।','hi'),
('CH03','दुरुधरा योग','Duradhura','चन्द्र योग','6.7','shubh','चन्द्रमा से द्वितीय व द्वादश दोनों भावों में ग्रह हों (सूर्य को छोड़कर)।','त्यागशील, सुखी, धनी, सवारियों की कमी न रहे, अनेक सांसारिक सुख-साधनों का भोग करे।','hi'),
('CH04','केमद्रुम योग','Kemadruma','चन्द्र योग','6.7','ashubh','चन्द्रमा से द्वितीय व द्वादश दोनों भावों में कोई ग्रह न हो। (भंग: चन्द्र के साथ ग्रह हो, लग्न से केन्द्र में ग्रह हो, अथवा चन्द्र से केन्द्र में ग्रह हो तो केमद्रुम नहीं होता)।','मलिन, दुःखी, निर्धन, दूसरे की मातहती में काम करने वाला, नगण्य।','hi'),
('SU01','शुभ वेसि योग','Shubha Vesi','सूर्य योग','6.8-9','shubh','सूर्य से द्वितीय भाव में एक या अधिक शुभ ग्रह (चन्द्र को छोड़कर) हों।','देखने में सुन्दर, सुखी, गुणनिधि, धीर, धार्मिक, अनेक व्यक्तियों पर हुकूमत करने वाला।','hi'),
('SU02','शुभ वासि योग','Shubha Vasi','सूर्य योग','6.8-9','shubh','सूर्य से द्वादश भाव में एक या अधिक शुभ ग्रह (चन्द्र को छोड़कर) हों।','अति सुन्दर, दाता, राजा का प्रिय (अच्छे ओहदे वाला), विख्यात; सब लोग चाहें।','hi'),
('SU03','शुभ उभयचरी योग','Shubha Ubhayachari','सूर्य योग','6.8-9','shubh','सूर्य से द्वितीय व द्वादश दोनों ओर शुभ ग्रह (चन्द्र को छोड़कर) हों।','वाग्मी (अच्छा बोलने वाला), प्रिय वचन बोलने वाला, यशस्वी, धनी, अंग मनोहर, सबको प्रसन्न करने वाला।','hi'),
('SU04','पाप वेसि योग','Papa Vesi','सूर्य योग','6.8-10','ashubh','सूर्य से द्वितीय भाव में पाप ग्रह हों।','अन्याय से दूसरों की निन्दा करने वाला, कान्तिहीन, छोटे लोगों की सोहबत, स्वयं दुर्जन।','hi'),
('SU05','पाप वासि योग','Papa Vasi','सूर्य योग','6.8-10','ashubh','सूर्य से द्वादश भाव में पाप ग्रह हों।','दूसरों की निन्दा करने वाला, मायावी, दुष्टों का मित्र, स्वयं दुराचरण करने वाला, शास्त्रों की दुहाई देने वाला।','hi'),
('SU06','पाप उभयचरी योग','Papa Ubhayachari','सूर्य योग','6.8-10','ashubh','सूर्य से द्वितीय व द्वादश दोनों ओर पाप ग्रह हों।','विद्याहीन, भाग्यहीन, धनहीन, चित्त सदैव दुःखित, अपकीर्ति (निन्दा) प्राप्त होती है।','hi'),
('LG01','शुभ कर्त्री योग','Shubha Kartari','लग्न योग','6.8','shubh','लग्न के दोनों ओर अर्थात् द्वितीय व द्वादश स्थान में शुभ ग्रह बैठे हों।','शुभ फल प्रदान करने वाला योग।','hi'),
('LG02','पाप कर्त्री योग','Papa Kartari','लग्न योग','6.8','ashubh','लग्न के दोनों ओर (द्वितीय व द्वादश में) पाप ग्रह हों।','अशुभ फल प्रदान करने वाला योग।','hi'),
('LG03','सुशुभ योग','Sushubha','लग्न योग','6.8','shubh','लग्न से द्वितीय में शुभ ग्रह बैठा हो और इस शुभ ग्रह को कोई पाप ग्रह न देखता हो।','शुभ फल; सुनफा योग के समान फल।','hi'),
('CY01','गजकेसरी योग','Gajakesari / Kesari','चन्द्र योग','6.14-16','shubh','चन्द्रमा से केन्द्र (1,4,7,10) में बृहस्पति हो (अथवा बृहस्पति से केन्द्र में चन्द्र)।','केसरी (शेर) की तरह शत्रुवर्ग को नष्ट करने वाला, सभाओं में प्रौढ़ वक्ता, राजसवृत्ति वाला, दीर्घायु, तीव्र बुद्धि, महान यश।','hi'),
('CY02','शकट योग','Shakata','चन्द्र योग','6.14-17','ashubh','चन्द्रमा से 6, 8 या 12वें भाव में बृहस्पति हो; किन्तु चन्द्रमा लग्न से केन्द्र में हो तो शकट योग नहीं बनता।','अत्यन्त दुःखी, हृदय में दुःख का कांटा, प्रसिद्धि नहीं, साधारण जीवन; कभी सितारा तेज तो कभी बिलकुल गिर जाए।','hi'),
('CY03','अधम योग','Adhama','चन्द्र-सूर्य योग','6.14 (टिप्पणी)','ashubh','सूर्य से केन्द्र (1,4,7,10) में चन्द्रमा हो।','अधम योग (निम्न फल देने वाला)।','hi'),
('CY04','सम योग','Sama','चन्द्र-सूर्य योग','6 (श्लोक टिप्पणी)','mishrit','सूर्य से पणफर स्थान (2,5,8,11) में चन्द्रमा हो।','सम (मध्यम) फल देने वाला योग।','hi'),
('CY05','वरिष्ठ योग','Varishtha','चन्द्र-सूर्य योग','6 (श्लोक टिप्पणी)','shubh','सूर्य से तृतीय, षष्ठ, नवम या द्वादश (3,6,9,12) स्थान में चन्द्रमा हो।','वरिष्ठ (उत्तम) योग।','hi'),
('MB01','महाभाग्य योग (पुरुष)','Mahabhagya (Male)','महाभाग्य योग','6.15','shubh','पुरुष जन्म: (1) दिन में जन्म (सूर्योदय के बाद व सूर्यास्त के पहले), (2) लग्न विषम राशि (1,3,5,7,9,11) का, (3) सूर्य विषम राशि में, (4) चन्द्रमा भी विषम राशि में हो। चारों बातें आवश्यक।','सबके नेत्रों को आनन्द देने वाला, उदार, विख्यात, निर्मल चरित्र, भूमि का स्वामी, राजा के समान ऐश्वर्यशाली।','hi'),
('MB02','महाभाग्य योग (स्त्री)','Mahabhagya (Female)','महाभाग्य योग','6.15','shubh','स्त्री जन्म: (1) रात्रि में जन्म (सूर्यास्त के बाद व सूर्योदय के पहले), (2) लग्न सम राशि (2,4,6,8,10,12) का, (3) चन्द्रमा सम राशि में, (4) सूर्य सम राशि में हो। चारों बातें आवश्यक।','उत्तम चरित्र की, सौभाग्यशालिनी, धनवती; पति, पुत्र, पौत्रों का सुख चिरकाल तक, सदैव सौभाग्यवती।','hi'),
('VA01','वसुमान् योग','Vasuman','धन/यश योग','6.19-21','shubh','समस्त शुभ ग्रह लग्न से (अथवा चन्द्रमा से) उपचय स्थानों (3,6,10,11) में हों।','सदैव अपने घर में रहे, पास बहुत द्रव्य (धन) हो; धनी।','hi'),
('VA02','अमला योग','Amala','धन/यश योग','6.19-21','shubh','लग्न से अथवा चन्द्रमा से दशम भाव में शुभ ग्रह हो।','भूमि का स्वामी, धनी, नीतिज्ञ, पुत्र व सम्पत्ति से युक्त, यशस्वी; चिरस्थायी कीर्ति।','hi'),
('VA03','पुष्कल योग','Pushkala','धन/यश योग','6.19-21','shubh','लग्न का स्वामी और चन्द्रमा जिस राशि में है उसका स्वामी—एक साथ केन्द्र में हों, किसी अभिमित्र (अधिमित्र) के घर में हों, और कोई बलवान ग्रह लग्न को देखे।','राजाओं द्वारा सम्मानित, धनी व प्रसिद्ध, उत्तम वस्त्र व आभूषण धारण, शुभ वाणी, बहुतों का स्वामी, श्रेष्ठ पदवी।','hi'),
('ML01','शुभ माला योग','Shubha Mala','माला योग','6.21-25','shubh','समस्त शुभ ग्रह लग्न से पंचम, षष्ठ, सप्तम (5,6,7) घरों में क्रम से हों। (कुछ मत: सब ग्रह इन स्थानों में)','अनेक व्यक्तियों पर अधिकार, भोगी, दाता, बन्धुप्रिय, उत्तम स्त्री-पुत्रों से युक्त, धीर, राजा द्वारा प्रशंसित।','hi'),
('ML02','अशुभ माला योग','Ashubha Mala','माला योग','6.21-25','ashubh','समस्त ग्रह षष्ठ, अष्टम, द्वादश (6,8,12) इन स्थानों में क्रम से हों।','दूसरों का वध करने वाले, कृतघ्न, कलहप्रिय (झगड़ालू), कुमार्गगामी, कायर; लोग निन्दा करें।','hi'),
('ML03','लक्ष्मी योग','Lakshmi','धन/राज योग','6.21-25','shubh','नवमेश (भाग्येश) और शुक्र दोनों अपने घर में या उच्चराशि में स्थित होकर लग्न से केन्द्र या त्रिकोण में हों।','तेजस्वी, अपने लोगों की रक्षा करने वाला, नीरोग; घोड़ा-हाथी-पालकी की सवारी, दानवीरता की प्रशंसा, पृथ्वी का श्रेष्ठ स्वामी—उत्तम राजयोग।','hi'),
('ML04','गौरी योग','Gauri','धन/राज योग','6.21-26','shubh','चन्द्रमा स्वराशि या उच्चराशि का होकर लग्न से केन्द्र या त्रिकोण में हो और बृहस्पति उसे देखता हो।','सुन्दर शरीर, राजा का मित्र, सद्गुणों व पुत्रों से युक्त, शत्रुओं को जीतने वाला, प्रशंसित, मुख कमल के समान।','hi'),
('VD01','सरस्वती योग','Saraswati','विद्या योग','6.27','shubh','बुध, बृहस्पति, शुक्र लग्न से केन्द्र (1,4,7,10), त्रिकोण (5,9) या द्वितीय स्थान में हों और बृहस्पति स्वराशि/मित्रराशि/उच्चराशि में बलवान हो।','अति बुद्धिमान, नाटक-गद्य-पद्य (काव्य) व गणित शास्त्र में महान, विद्वान; काव्य रचना व शास्त्रार्थ में पारंगत, तीनों लोकों में कीर्ति, अति धनी।','hi'),
('TD01','श्रीकंठ योग','Shrikantha','त्रिदेव योग','6.28-29','shubh','लग्न का स्वामी, सूर्य और चन्द्रमा—तीनों स्वराशि/मित्रराशि/उच्चराशि में स्थित होकर लग्न से केन्द्र या त्रिकोण में हों।','रुद्राक्ष धारण करने वाला, विभूति से धवल कान्ति वाला महात्मा, शिवभक्त, धार्मिक व सदाचारी, साधु-उपकारी, तेजस्वी।','hi'),
('TD02','श्रीनाथ योग','Shrinatha','त्रिदेव योग','6.28-30','shubh','बुध, शुक्र और भाग्यस्थान (नवम) का स्वामी—तीनों उच्चराशि/स्वराशि/मित्रराशि में स्थित होकर लग्न से केन्द्र या त्रिकोण में हों।','लक्ष्मीवान (धनी), सरस वचन बोलने वाला, नारायण के चिह्नों (शंख, चक्र) से युक्त, विष्णुभक्तों में आदरणीय, सुन्दर, उत्तम पुत्र-स्त्री सुख।','hi'),
('TD03','वैरिञ्चि योग','Vairinchi','त्रिदेव योग','6.28-31','shubh','पञ्चम का स्वामी, बृहस्पति और शनि—तीनों उच्चराशि/स्वराशि/मित्रराशि में स्थित होकर लग्न से केन्द्र या त्रिकोण में हों।','बहुत बुद्धिमान, वैदिक धर्माचार्य, ब्रह्मज्ञान परायण, गुणी, प्रसन्नचित्त, वेदोक्त मार्ग पर, सौम्य वचन, धन-पुत्र-स्त्री सुख, दीर्घायु, जितेन्द्रिय; राजा भी नमस्कार करें।','hi'),
('SS01','महायोग (परिवर्तन)','Mahayoga (Parivartana ×28)','षट्षष्टि योग','6.32-34','shubh','दो शुभ भावों (1,2,4,5,7,9,10,11) के स्वामी परस्पर स्थान परिवर्तन करें (जैसे लग्नेश द्वितीय में व द्वितीयेश लग्न में) — ऐसे 28 संयोग।','लक्ष्मी का कृपापात्र (धनी), अनेक व्यक्तियों का स्वामी, सुन्दर वस्त्र-आभूषण, राजा/सरकार से सम्मानित व पुरस्कृत, उच्च पदवी, धन-पुत्र-सवारी सुख।','hi'),
('SS02','खल योग (परिवर्तन)','Khala (Parivartana ×8)','षट्षष्टि योग','6.32-34','mishrit','तृतीय भाव के स्वामी का अन्य भावों (लग्न/धन/सुख/पंचम/सप्तम/भाग्य/राज्य/लाभ) के स्वामी से परस्पर स्थान परिवर्तन — ऐसे 8 संयोग।','कभी अनाचार तो कभी सदाचार के मार्ग पर, कभी अखिल सौभाग्यशाली तो कभी दरिद्र, शुभ-अशुभ दोनों प्रभाव—अशुभ प्रभाव अधिक।','hi'),
('SS03','दैन्य योग (परिवर्तन)','Dainya (Parivartana ×30)','षट्षष्टि योग','6.32-34','ashubh','षष्ठ, अष्टम या द्वादश (दुःस्थान) के स्वामी का किसी अन्य भाव के स्वामी से परस्पर स्थान परिवर्तन — ऐसे 30 संयोग।','स्वयं मूर्ख, दूसरों की निन्दा करने वाला, दुष्टकर्मा, सदैव शत्रुओं से पीड़ित, क्रूर वचन, अस्थिर मति; कार्यों में विघ्न व विच्छेद।','hi'),
('KP01','कहल योग','Kahala','केन्द्र-त्रिकोण योग','6.35-36','shubh','लग्नेश जिस राशि में हो उसका स्वामी अपनी उच्चराशि/स्वराशि में स्थित होकर केन्द्र या त्रिकोण में हो।','अच्छी बुद्धि वाला, वर्द्धिष्णु (उन्नतिशील), श्रेष्ठ, प्रसन्न, दूसरों का कल्याण करने वाला, जनता द्वारा मान्य।','hi'),
('KP02','पर्वत योग','Parvata','केन्द्र-त्रिकोण योग','6.35-36','shubh','लग्नेश जिस राशि में है उस राशि का स्वामी अपनी उच्चराशि या स्वराशि में स्थित होकर केन्द्र या त्रिकोण में हो।','स्थिर कार्य करने वाला (मकान, बाग, फैक्टरी, धर्मशाला, कुआँ-तालाब आदि), परोपकारी; क्षितीश्वर (भूमि का स्वामी) या उच्च पदाधिकारी।','hi'),
('KP03','राजयोग (नवम-दशमेश)','Rajayoga (9-10 lords)','केन्द्र-त्रिकोण योग','6.37-38','shubh','नवम (भाग्य) और दशम (कर्म) भाव के स्वामी दोनों संयुक्त होकर किसी शुभ भाव में एक साथ बैठें।','राजा या राजतुल्य पदवी वाला; यात्रा में भेरी-शंख-ढोल बजें, सिर पर छत्र, हाथी-घोड़े-पालकी की सवारियाँ, भाट-चारण स्तुति गाएँ, श्रेष्ठ वनिताओं का भोग व सम्पत्ति।','hi'),
('KP04','शंख योग','Shankha','केन्द्र-त्रिकोण योग','6.37-38','shubh','किसी केन्द्र (1,4,7,10) का स्वामी किसी त्रिकोण (5,9) के स्वामी के साथ संयुक्त होकर किसी शुभ भाव में बैठे।','राजा या राजतुल्य पदवी; वैभव, सम्मान व सम्पत्ति सम्पन्न।','hi'),
('NB01','वीणा (वल्लकी) योग','Veena / Vallaki','नाभस योग','6.39-41','shubh','सूर्य आदि सातों ग्रह (राहु-केतु छोड़कर) सात अलग-अलग राशियों में हों।','नाचने-गाने-बजाने का शौकीन, धनी।','hi'),
('NB02','दाम योग','Dama','नाभस योग','6.39-41','shubh','सातों ग्रह कुल 6 राशियों में हों।','राजा के समान दूसरों का उपकार करने वाला, स्वयं त्यागी।','hi'),
('NB03','पाश योग','Pasha','नाभस योग','6.39-41','shubh','सातों ग्रह कुल 5 राशियों में हों।','भोगी, धनी, सुशील, बन्धुयुक्त।','hi'),
('NB04','केदार योग','Kedara','नाभस योग','6.39-41','shubh','सातों ग्रह कुल 4 राशियों में हों।','खेत, खेती व लक्ष्मी का शुभ योग।','hi'),
('NB05','शूल योग','Shula','नाभस योग','6.39-41','ashubh','सातों ग्रह कुल 3 राशियों में हों।','हिंसक प्रवृत्ति का, क्रोधी, दरिद्र।','hi'),
('NB06','युग योग','Yuga','नाभस योग','6.39-41','ashubh','सातों ग्रह कुल 2 राशियों में हों।','पाखण्डी व धनहीन।','hi'),
('NB07','गोल योग','Gola','नाभस योग','6.39-41','ashubh','सातों ग्रह केवल एक ही राशि में हों।','आलसी, अल्पायु, दरिद्र, पापी, म्लेच्छों की संगति; शिल्पकार्य में भी निपुण नहीं।','hi'),
('AD01','अधियोग','Adhi Yoga','अधियोग','6.42-43','shubh','चन्द्रमा से (अथवा लग्न से) 6, 7, 8 भावों में बुध, बृहस्पति, शुक्र (शुभ ग्रह) स्थित हों। तीनों घर भरे हों या कोई खाली भी हो सकता है।','यदि तीनों पूर्ण बली हों तो भूपति (राजा); मध्यबली हों तो मन्त्री; हीनबली हों तो नेता। लक्ष्मीवान, दीर्घायु, मनस्वी, स्थिर सम्पत्ति, अनेकों पर हुकूमत, शत्रुओं को पराजित करने वाला, प्रसिद्ध।','hi'),
('BV01','चामर योग','Chamara','भाव योग','6.44-56','shubh','लग्न में शुभ ग्रह हों या लग्न को शुभ ग्रह देखें, और लग्नेश अस्त न होकर उत्तम स्थान में स्वराशि/स्वक्षेत्री होकर बैठा हो।','शुक्ल पक्ष के चन्द्रमा की तरह वृद्धि को प्राप्त, सुन्दर व सुशील, लक्ष्मीवान, कीर्तिवान, दीर्घायु, जनपति (अनेकों पर हुकूमत)।','hi'),
('BV02','धेनु योग','Dhenu','भाव योग','6.44-56','shubh','द्वितीय घर में शुभ ग्रह हों या शुभ ग्रह देखें, और द्वितीयेश उदित होकर स्वराशि/उच्चराशि में सुस्थान में बैठा हो।','स्वर्ण, धन, धान्य व रत्न से समृद्ध, राजराज के समान (धनी); विद्या, कुटुम्ब, भोजन-पान का सुख।','hi'),
('BV03','शौर्य योग','Shaurya','भाव योग','6.44-56','shubh','तृतीय भाव में शुभ ग्रह हों या देखें, तृतीयेश अस्त न होकर स्वराशि/उच्चराशि में उत्तम स्थान में हो।','बहुत पराक्रमी, छोटे भाई यशस्वी व भ्रातृभक्त, स्वयं यशस्वी, राज्य कार्य में निरत, अच्छे सरकारी ओहदे पर।','hi'),
('BV04','जलधि (अम्बुधि) योग','Jaladhi / Ambudhi','भाव योग','6.44-56','shubh','चतुर्थ स्थान में शुभ ग्रह हों या देखें, चतुर्थेश अस्त न होकर स्वराशि/उच्चराशि में उत्तम स्थान में हो।','गो-सम्पत्ति, धन-धान्य पर्याप्त, सुन्दर मकान, बन्धुओं से सुख, उत्तम स्त्री-रत्न-वस्त्र-भूषण, हाथी-घोड़े-पालकी सुख, धार्मिक कार्यों में प्रवृत्त।','hi'),
('BV05','छत्र योग','Chatra','भाव योग','6.44-56','shubh','पञ्चम भाव में शुभ ग्रह हों या देखें, पंचमेश अस्त न होकर स्वराशि/उच्चराशि में उत्तम स्थान में हो।','संसार के सब सौभाग्यों से युक्त, सन्तान सुख, धनी, यशस्वी, बुद्धिमान, तीक्ष्ण बुद्धि, राजा का मन्त्री, राजा/सरकार से सम्मान।','hi'),
('BV06','अस्त्र योग','Astra','भाव योग','6.44-56','mishrit','षष्ठ भाव का स्वामी अस्त न होकर स्वराशि/उच्चराशि में उत्तम स्थान में बैठा हो और छठा भाव शुभ ग्रह युत या शुभ ग्रहों से दृष्ट हो।','बलवान शत्रुओं को अपनी जबरदस्त ताकत से दबा देने वाला, क्रूर प्रवृत्ति, अभिमानी, दृढ़ शरीर (शरीर पर व्रण के चिह्न), विवादकारी।','hi'),
('BV07','काम योग','Kama','भाव योग','6.44-56','shubh','सप्तम स्थान पर शुभ ग्रहों की दृष्टि हो व शुभ ग्रह बैठे हों, सप्तमेश अस्त न होकर स्वराशि/उच्चराशि में उत्तम स्थान में हो।','परदार-पराङ्मुख (व्यभिचारी नहीं), उत्तम स्त्री-सन्तान-बन्धु सुख, शुभ गुणों से लक्ष्मी प्राप्त, पिता से अधिक उच्च पदवी।','hi'),
('BV08','आसुर योग','Asura','भाव योग','6.44-56','ashubh','अष्टम स्थान में शुभ ग्रह हों या देखें, अष्टमेश स्वराशि/उच्चराशि का अस्तंगत न होकर उत्तम स्थान में बैठा हो।','(निकृष्ट फल) स्वार्थी, कुकर्मी, दरिद्री, दुराग्रही (जिद्दी), चुगलखोर, दूसरों का काम बिगाड़ने वाला; अपने दुष्कर्मों से स्वयं हानि व दुःख।','hi'),
('BV09','भाग्य योग','Bhagya','भाव योग','6.44-56','shubh','नवम भाव में शुभ ग्रह बैठे हों या देखें, नवमेश सूर्य किरणों से अस्तंगत न होकर स्वराशि/उच्चराशि में उत्तम स्थान में बलवान हो।','पालकी में चलने पर दोनों ओर चंवर, आगे-पीछे बाजे; सदैव लक्ष्मी सम्पन्न, बड़े लोग नमस्कार करें, माता-पिता-पितर-ब्राह्मण-देवताओं का पूजक, अपने कुल की कीर्ति बढ़ाने वाला, आचारनिष्ठ, सहृदय।','hi'),
('BV10','ख्याति योग','Khyati','भाव योग','6.44-56','shubh','दशम भाव में शुभ ग्रह बैठे हों व शुभ ग्रह देखें, दशमेश अस्त न होकर उत्तम स्थान में अपनी उच्चराशि/स्वराशि में हो।','उत्तम कर्म करने वाला, सब प्रशंसा करें, नृप होकर प्रजा की रक्षा करे, लोक में ख्याति; स्त्री-पुत्र-मित्र-धन का पूर्ण सुख, भाग्यवान।','hi'),
('BV11','सुपारिजात योग','Suparijata','भाव योग','6.44-56','shubh','लाभेश (एकादशेश) अस्त न होकर अपनी स्वराशि/उच्चराशि में स्थित होकर लग्न से उत्तम स्थान में हो व लाभ भाव में शुभ ग्रह हों या शुभ ग्रह देखें।','अच्छे कुटुम्ब वाला, अर्थ संग्रह से धनी, नित्य मंगल (शुभ) कार्यों में भाग लेने वाला, पुण्य कथाओं के श्रवण व भक्ति में समय लगाने वाला, विद्वान व सत्कर्म करने वाला।','hi'),
('BV12','मुसल योग','Musala','भाव योग','6.44-56','mishrit','द्वादश घर में शुभ ग्रह बैठे हों या शुभ ग्रह देखें, और द्वादशेश स्वराशि/उच्चराशि में स्थित होकर लग्न से उत्तम स्थान में बैठा हो।','बड़ी कठिनता से धन प्राप्ति, सम्पत्ति चंचल, बहुत व्यय (परन्तु शुभ कार्यों में), चपल, किन्तु जीवन के अन्त में स्वर्ग प्राप्ति।','hi'),
('DR01','अवयोग','Avayoga','दरिद्र/नकारात्मक योग','6.57-58','ashubh','लग्न या लग्नेश अशुभ (पाप) ग्रह से युत या दृष्ट हो और लग्नेश दुःस्थान (6,8,12) में हो।','स्थिति बहुत चंचल, दुर्जनों की संगति, शरीर में रोग, चरित्र अच्छा नहीं, अल्पायु, अप्रसिद्ध, घोर दरिद्रता व अपमान।','hi'),
('DR02','निःस्व योग','Nihsva','दरिद्र/नकारात्मक योग','6.57-58','ashubh','द्वितीयेश पाप ग्रह से युत/दृष्ट हो या दुःस्थान (6,8,12) में हो, और द्वितीय भाव में पाप ग्रह हों या पाप ग्रह देखते हों।','दरिद्री, दाँत व नेत्र खराब, अच्छे वचन न बोले, कुटुम्ब निष्फल, बुद्धि-पुत्र-विद्या-वैभव से हीन, शत्रु धन हर लें।','hi'),
('DR03','मृति योग','Mriti','दरिद्र/नकारात्मक योग','6.57-58','ashubh','तृतीयेश दुःस्थान (6,8,12) में स्थित हो और तृतीय भाव अशुभ ग्रहों से युत/दृष्ट हो।','शत्रुओं से पराजित, अनुचित कर्म, परिश्रम से खिन्न, निर्लज्ज; बल व धन का हरण, भाई-बहन का सुख न हो।','hi'),
('DR04','कुहू योग','Kuhu','दरिद्र/नकारात्मक योग','6.57-58','ashubh','चतुर्थेश (या चतुर्थ भाव/लग्न) अशुभ ग्रहों से युत/दृष्ट हो और चतुर्थेश दुःस्थान (6,8,12) में हो।','माता, सवारी, मित्र, आभूषण व बन्धुओं का सुख न मिले; सुखहीन, कुस्त्री में रत, क्लेश उठाने वाला।','hi'),
('DR05','पामर योग','Pamara','दरिद्र/नकारात्मक योग','6.59','ashubh','पंचमेश या पंचम भाव अशुभ ग्रह से युत/दृष्ट हो और पंचमेश दुःस्थान में पड़ा हो।','दुःख से जीवन, असत्यभाषी, अविवेकी, बंचक, सन्तान सुख नहीं, पितृद्वेषी, नास्तिक, दुष्टों की संगति, पेटू।','hi'),
('DR06','हर्ष योग','Harsha','दुःस्थान (शुभ) योग','6.60','shubh','षष्ठ घर अशुभ ग्रहों से युत/दृष्ट हो और षष्ठेश दुःस्थान (6,8,12) में स्थित हो।','भाग्यवान, दृढ़ शरीर, सुखी, भोगी, शत्रुओं को पराजित करने वाला, पापभीरु, विख्यात व प्रधान व्यक्तियों का प्रिय, धन-पुत्र-मित्र सुख, यशस्वी।','hi'),
('DR07','दुष्कृति योग','Dushkriti','दरिद्र/नकारात्मक योग','6.61','ashubh','सप्तमेश या सप्तम भाव अशुभ ग्रहों से युत/दृष्ट हो और सप्तमेश दुःस्थान में पड़ा हो।','पत्नी वियोग (मृत्यु/अलगाव/रोगिणी), परस्त्री में रति की इच्छा, कष्टमय यात्रा, बन्धुओं द्वारा तिरस्कार, राजा/सरकार से पीड़ा, प्रमेह आदि इन्द्रिय रोग।','hi'),
('DR08','सरल योग','Sarala','दुःस्थान (शुभ) योग','6.62','shubh','अष्टम भाव का स्वामी दुःस्थान (6,8,12) में बैठा हो। (टिप्पणी: अष्टम में पाप ग्रह का बैठना उत्तम नहीं)','दीर्घायु, दृढ़ मति (निर्भय), लक्ष्मीवान, विद्या-पुत्र-धन युत, उद्योग में सफल, निर्मल, शत्रुओं को जीतने वाला, विख्यात।','hi'),
('DR09','निर्भाग्य योग','Nirbhagya','दरिद्र/नकारात्मक योग','6.63','ashubh','नवमेश लग्न से 6,8,12 भाव में हो व नवम गृह पर अशुभ ग्रहों की दृष्टि हो या अशुभ ग्रह बैठे हों (या नवमेश पाप ग्रह युत/दृष्ट हो)।','बहुत दुःख उठाने वाला, पुराने कपड़े पहनने वाला, दुर्गति, साधु व गुरुओं की निन्दा; पैतृक सम्पत्ति नष्ट।','hi'),
('DR10','दुर्योग','Duryoga','दरिद्र/नकारात्मक योग','6.64','ashubh','दशम में क्रूर ग्रह बैठे हों व दशमेश अशुभ ग्रहों से युत/दृष्ट हो और वह (दशमेश) 6,8,12 स्थान में पड़ा हो।','पूर्ण परिश्रम पर भी सफलता नहीं, प्रयास निष्फल, प्रायः प्रवासी, आदर नहीं, दूसरों से द्रोह, अपने पेट पालने की ही फिक्र।','hi'),
('DR11','दरिद्र योग','Daridra','दरिद्र/नकारात्मक योग','6.65','ashubh','एकादशेश (लाभेश) दुःस्थान (6,8,12) में हो या त्रिक में हो या अशुभ ग्रहों से युत/दृष्ट हो।','कर्जदार, अत्यन्त दरिद्री, कान की बीमारी, अच्छे भाइयों से हीन, दुष्कार्य करने वाला, अप्रशस्त वचन, दूसरों का नौकर, दुःखी।','hi'),
('DR12','विमल योग','Vimala','दुःस्थान (शुभ) योग','6.66-69','shubh','द्वादश घर का स्वामी दुःस्थान (6,8,12) में हो व अशुभ ग्रहों से युत/दृष्ट हो। (टिप्पणी: द्वादशेश का दुःस्थान में जाना शुभ माना गया)','व्यय (खर्च) कम व धन की वृद्धि, सुखी, स्वतंत्र, सद्गुणों के लिए विख्यात, उत्तम कार्य करने वाला, सबके अनुकूल आचरण।','hi'),
('DR13','दुर्योग (त्रिक बलवान)','Duryoga (Trik strong)','दरिद्र/नकारात्मक योग','6.70','ashubh','षष्ठ, अष्टम व द्वादश के स्वामी बलवान होकर केन्द्र (1,4,7,10) या त्रिकोण (5,9) में हों, तथा लग्न-चतुर्थ-नवम-दशम के स्वामी निर्बल/अस्त होकर 6,8,12 में हों।','खराब योग—यह उलटा हो (6,8,12 के स्वामी निर्बल दुःस्थान में, तथा 1,4,9,10 के स्वामी बलवान सुस्थान में) तो योगवान धनपति, राजा, सुखी व धार्मिक होता है।','hi'),
('RY01','त्रि-ग्रह उच्च केन्द्र राजयोग','Three Planets Exalted in Kendra','राजयोग','7.1-2','shubh','तीन या अधिक ग्रह उच्च राशि या स्वराशि में स्थित होकर केन्द्र (1,4,7,10) में हों। (पाँच या अधिक हों तो सम्राट)।','प्रसिद्ध राजा; पाँच या अधिक हों तो पृथ्वीपति (सम्राट), हाथी-घोड़ों के झुंड वाला अत्यन्त वैभवशाली राजा।','hi'),
('RY02','वक्री/नीच शुभ राजयोग','Retrograde/Debilitated Bright','राजयोग','7.3','shubh','एक भी ग्रह सुस्थान में (6,8,12 में नहीं) व वक्री हो (चाहे नीच भी हो), किन्तु अस्त न हो व उज्ज्वल प्रभा से युक्त हो। दो-तीन ऐसे हों तो और प्रबल।','राजा के सदृश वैभवशाली; दो-तीन हों तो राजा; बहुत से उत्तम राशि/नवांश में हों तो मुकुट-छत्र-चँवर से शोभायमान अत्यन्त वैभवशाली राजा।','hi'),
('RY03','दिग्बली राजयोग','Digbala Rajayoga','राजयोग','7.4','shubh','दो या अधिक ग्रह दिग्बली हों। दिग्बल: सूर्य व मंगल दशम में, बुध व बृहस्पति लग्न में, चन्द्र व शुक्र चतुर्थ में, शनि सप्तम में। (चार-पाँच दिग्बली हों तो और प्रबल)','चाहे अधम वंश में भी पैदा हो, राजा होता है और सर्वत्र विजय प्राप्त करता है।','hi'),
('RY04','वर्गोत्तम लग्न-चन्द्र राजयोग','Vargottama Lagna-Chandra','राजयोग','7.5','shubh','लग्न वर्गोत्तम नवांश का हो और चन्द्रमा भी वर्गोत्तम नवांश का हो, तथा चन्द्रमा के अतिरिक्त अन्य चार ग्रह लग्न को देखते हों।','चाहे अधम वंश में भी पैदा हुआ हो, राजा हो जाता है।','hi'),
('RY05','वर्गोत्तम लग्नेश राजयोग','Vargottama Lagnesha','राजयोग','7.6','shubh','लग्नेश वर्गोत्तम होकर 1,4,7,9,10 भावों में हो और नवमेश अपनी स्वराशि/उच्चराशि में वर्गोत्तम होकर केन्द्र या नवम में हो।','अत्यन्त वैभवशाली राजा, हाथी के कन्धे पर सोने के सुन्दर विमान (अम्बारी) में चलता है, जिसमें दोनों ओर चँवर हिलते रहते हैं।','hi'),
('RY06','पूर्ण चन्द्र दृष्ट राजयोग','Bright Moon Aspected','राजयोग','7.7','shubh','(क) उज्ज्वल (पक्षबली) चन्द्रमा को स्वराशि/उच्चराशि में बैठा ग्रह पूर्ण दृष्टि से देख रहा हो। (ख) पूर्ण कान्ति (पूर्णिमा का) चन्द्रमा लग्न के अतिरिक्त अन्य केन्द्रों में हो।','चाहे निषाद कुल में पैदा हो, राजा होता है; हाथी व घोड़ों से युक्त राजा।','hi'),
('RY07','अश्विनी-शुक्र राजयोग','Venus in Ashwini Lagna','राजयोग','7.8','shubh','(क) शुक्र अश्विनी नक्षत्र में स्थित होकर लग्न में हो और उसे तीन ग्रह देखते हों। (ख) लग्नेश बलवान हो व शुक्र के साथ द्वितीय स्थान में हो (नीच/शत्रु राशि नहीं)।','प्रबल राजा जो अपने शत्रुओं को जीतता है; राजा।','hi'),
('RY08','मंगल लग्न राजयोग','Mars in Own Sign Lagna','राजयोग','7.9','shubh','(क) मंगल मेष, सिंह या धनु राशि में स्थित होकर लग्न में हो व उसे मित्र ग्रह देखता हो। (ख) दशमेश नवम भाव में व नवमेश दशम भाव में हो।','मनुष्य राजा होता है; सब उसकी प्रशंसा करते हैं—प्रबल राजयोग कारक।','hi'),
('RY09','धनु-सूर्य-चन्द्र राजयोग','Sun-Moon-Saturn-Mars','राजयोग','7.10','shubh','सूर्य धनु राशि के आधे में (15 अंश तक) हो व वहीं चन्द्रमा हो, लग्न में शनि हो, तथा अति बलवान मंगल उच्च राशि में हो।','बड़ा पराक्रमी राजा, उसके भय से शत्रु दूर से ही नमस्कार करें।','hi'),
('RY10','सिंह नवांश चन्द्र राजयोग','Full Moon in Leo Navamsha','राजयोग','7.11','shubh','अमृत/मृणाल के समान सफेद पूर्ण बिम्ब वाला (पूर्णिमा के आसपास का) चन्द्रमा सिंह नवांश में हो और शुभ ग्रह (पाप ग्रह रहित) केन्द्र में हों।','राजा होता है और उसके बहुत से हाथी होते हैं।','hi'),
('RY11','पक्षबली चन्द्र राजयोग','Strong Moon Own Navamsha','राजयोग','7.12','shubh','चन्द्रमा गाय के दूध या शंख के समान उज्ज्वल कान्ति वाला (पक्ष बली) हो और तीन अन्य ग्रह (चन्द्र सहित चार) बलवान होकर अपने-अपने अंशों में हों; नीच/शत्रु राशि या वर्ग में न हों और शुभ ग्रह देखते हों।','भूमिपति होता है और शत्रुओं पर विजय प्राप्त करता है।','hi'),
('RY12','श्रेष्ठांश चन्द्र राजयोग','Moon in Best Navamsha','राजयोग','7.13','shubh','लग्न में कोई पाप ग्रह न हो, चन्द्रमा श्रेष्ठ (उत्तम वर्ग) अंश में हो और चन्द्रमा को बलवान ग्रह देखता हो।','सुन्दर शरीर वाला, सर्व भूमि पर अधिकार वाला राजा।','hi'),
('RY13','नवम शुभ ग्रह राजयोग','Benefic in 9th House','राजयोग','7.14','shubh','बृहस्पति, बुध, शुक्र या चन्द्रमा—अस्त न हों व विशुद्ध शरीर वाले होकर नवम भाव में बैठे हों (उच्च/स्वराशि/शुभ दृष्ट) और मित्र ग्रहों से युत या वीक्षित हों।','महान राजा; प्रजा उसे देवता के सदृश मानती है।','hi'),
('RY14','मीन-मेष लग्न राजयोग','Pisces-Aries Combination','राजयोग','7.15','shubh','शुक्र, बृहस्पति व शनि मीन राशि में हों, चन्द्रमा पूर्ण (पूर्णिमा का) व अपनी उच्च राशि में हो, सूर्य को मंगल देखता हो और मेष लग्न हो।','बहुत बड़ा राजा; उसकी सेना के चलने से इतनी धूल उड़े कि दिन में भी संध्या-भ्रान्ति हो।','hi'),
('RY15','कर्क चन्द्र सम्राट योग','Emperor (Cancer Moon)','राजयोग','7.16','shubh','(क) रात्रि में जन्म हो, (ख) चन्द्रमा कर्क राशि में स्थित ग्रह दशम में हो, (ग) नीच/शत्रु राशि के ग्रह लग्न से 3,6,11 में हों या समस्त शुभ ग्रह परमोच्च होकर केन्द्र में हों व कोई शुभ ग्रह अस्त न हो।','समस्त संसार का एक छत्रपति राजा (क्षत्रियेश/सम्राट)।','hi'),
('RY16','वर्गोत्तम पूर्ण चन्द्र राजयोग','Full Moon Vargottama','राजयोग','7.17','shubh','पूर्णिमा का चन्द्र वर्गोत्तमांश में हो।','केवल इसी एक योग से महा प्रतापशाली राजा; सेना के घोड़ों के खुरों से उड़ी धूलि सूर्य को म्लान कर दे।','hi'),
('RY17','बृहस्पति-चन्द्र केन्द्र राजयोग','Jupiter-Moon Kendra','राजयोग','7.18','shubh','जन्म के समय बृहस्पति और चन्द्रमा केन्द्र (1,4,7,10) में हों, उनको शुक्र देखता हो और कोई ग्रह नीच राशि में न हो।','मनुष्य अनुपम कीर्ति वाला राजा होता है।','hi'),
('RY18','जलचर चन्द्र राजयोग','Moon in Watery Sign','राजयोग','7.19','shubh','चन्द्रमा जलचर राशि (कर्क/वृश्चिक/मीन) व नवांश में स्थित होकर लग्न में अपने वर्ग में या शुभ ग्रह के वर्ग में हो और कोई पाप ग्रह केन्द्र में न हो।','मनुष्य राजा होता है और बहुत हाथी उसके पास होते हैं।','hi'),
('RY19','चतुर्विध राजयोग','Four Rajayogas','राजयोग','7.20','shubh','(क) राजवंश में जन्म व शुक्र या बृहस्पति देखता हो। (ख) बृहस्पति (मकर छोड़कर) किसी राशि में लग्न में हो। (ग) लग्नेश बलवान होकर केन्द्र में हो। (घ) बुध को बृहस्पति देखता हो।','(क)(ख)(ग) राजा; (घ) उसकी सलाह को महाराजा भी मानें (राजमन्त्री)।','hi'),
('RY20','उच्च-मित्र दृष्ट राजयोग','Exalted Aspected by Friend','राजयोग','7.21','shubh','(क) एक भी ग्रह उच्च राशि में हो और उसको मित्र ग्रह देखते हों (मित्र ग्रह से युत हो तो धनवान)। (ख) सूर्य अपने नवांश में हो और चन्द्रमा कर्क राशि में हो (दोनों बलवान हों)।','राजा; उच्च ग्रह मित्र-युत हो तो धनवान। सूर्य-चन्द्र बलवान होने से सारी कुण्डली सुधर जाती है।','hi'),
('RY21','मीन पूर्ण चन्द्र राजयोग','Full Moon in Pisces','राजयोग','7.22','shubh','(क) चन्द्रमा पूर्ण प्रकाशमान होकर मीन राशि में हो और उसे मित्र ग्रह देखता हो। (ख) पूर्ण चन्द्रमा अपनी उच्चराशि में हो।','उत्तम राजयोग; अति उदार, सज्जनों द्वारा प्रशंसित।','hi'),
('RY22','अभिमित्रांश चन्द्र राजयोग','Moon in Friend Navamsha','राजयोग','7.23','shubh','(क) चन्द्रमा अपने अधिमित्र के अंश (नवांश) में हो और उस पर शुक्र की दृष्टि हो। (ख) साथ ही चन्द्रमा पर बृहस्पति की भी दृष्टि हो।','लक्ष्मी प्राप्ति के साथ उत्तम राजयोग; (ख) राजा।','hi'),
('RY23','चतुर्विध राजयोग (स्थान)','Four Positional Rajayogas','राजयोग','7.24','shubh','(क) जन्मनाथ (चन्द्रराशीश) से 3,6,11 में पाप ग्रह हों। (ख) मंगल व बुध लग्न से द्वितीय में हों। (ग) सूर्य व शुक्र लग्न से चतुर्थ में हों। (घ) मंगल दशम में, बृहस्पति लग्न में, शनि एकादश (10,1,11) में हों।','चारों उत्तम राजयोग हैं।','hi'),
('RY24','द्वितीयादि-नवम-लाभ राजयोग','2-9-11 Lords Rajayoga','राजयोग','7.25','shubh','(क) द्वितीय, नवम व एकादश—इन तीनों के स्वामियों में से एक भी ग्रह चन्द्रमा से केन्द्र में हो। (ख) द्वितीय, पञ्चम व एकादश इनमें से किसी का मालिक बृहस्पति हो।','उत्तम राजयोग होता है।','hi'),
('NBR01','नीचभंग राजयोग (चन्द्र-केन्द्र)','Neechabhanga (Moon Kendra)','नीचभंग राजयोग','7.26','shubh','कोई ग्रह नीच राशि में हो और (क) इस नीच राशि का स्वामी चन्द्रमा से केन्द्र में हो तथा (ख) जो ग्रह नीच है उसका उच्चनाथ भी चन्द्रमा से केन्द्र में हो। (उच्चनाथ = जिस राशि में ग्रह उच्च होता है उस राशि का स्वामी)','नीच भंग होकर उत्तम राजयोग बनता है—चक्रवर्ती राजा।','hi'),
('NBR02','नीचभंग राजयोग (परस्पर केन्द्र)','Neechabhanga (Mutual Kendra)','नीचभंग राजयोग','7.27','shubh','कोई ग्रह नीच राशि में हो तो (क) उस नीच राशि का स्वामी और (ख) जो ग्रह नीच का है उसका उच्चनाथ—दोनों परस्पर केन्द्र में हों।','नीच भंग राजयोग—समस्त भूपालों द्वारा वन्दित चक्रवर्ती।','hi'),
('NBR03','नीचभंग राजयोग (पूर्ण दृष्टि)','Neechabhanga (Full Aspect)','नीचभंग राजयोग','7.28','shubh','जिस राशि में नीच ग्रह हो उस राशि का स्वामी नीच ग्रह को पूर्ण दृष्टि से देखता हो। (यदि नीच ग्रह 6,8,12 में हो तो कम, सुस्थान में हो तो उत्तम)।','नीचभंग राजयोग; सुस्थान में हो तो बहुत उत्तम नीचभंग राजयोग।','hi'),
('NBR04','नीचभंग राजयोग (लग्न/चन्द्र केन्द्र)','Neechabhanga (Lagna/Moon Kendra)','नीचभंग राजयोग','7.29','shubh','कोई ग्रह नीच राशि में हो तो (क) इस नीच राशि का स्वामी अथवा (ख) नीच ग्रह का उच्चनाथ—इन दोनों में से एक भी लग्न या चन्द्र लग्न से केन्द्र में हो।','चक्रवर्ती नृप—धार्मिक, अन्य राजाओं द्वारा वन्दित पद, तेजस्वी, यशस्वी, भाग्यवान।','hi'),
('NBR05','नीचभंग राजयोग (नीचोच्चभेश)','Neechabhanga (Sign & Exalt Lords)','नीचभंग राजयोग','7.30','shubh','कोई ग्रह नीच राशि में हो, उस नीच राशि का स्वामी और नीच ग्रह जिस राशि में उच्च होता है उसका स्वामी—एक या दोनों लग्न से केन्द्र में हों।','नीचभंग राजयोग—भूपवन्दित चक्रवर्ती राजा।','hi')
INSERT INTO house_engine_config (cfg_key, cfg_value) VALUES
('phala_yoga_show','1'),
('phala_yoga_autodetect','1')
