-- =============================================================================
-- Auto Business — Phaladeepika yoga catalogue (migration 025)
-- All 106 yogas of Phaladeepika ch. 6 (Yogadhyaya) & ch. 7 (Rajayoga): id,
-- Hindi/English name, category, shloka ref, type, rule and result. DB rows
-- override the baked PhaladeepikaYogaData by yoga_id; the engine auto-detects
-- the computable subset from the D1 chart. Shown under the "योग" option.
-- Source: docs/Phaladeepika_Yoga_Rules.md.
-- =============================================================================
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS phaladeepika_yoga (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    yoga_id VARCHAR(16) NOT NULL,
    yoga_hi VARCHAR(64) NOT NULL,
    yoga_en VARCHAR(64) NOT NULL DEFAULT '',
    category VARCHAR(48) NOT NULL,
    ref VARCHAR(24) NOT NULL DEFAULT '',
    yoga_type VARCHAR(12) NOT NULL,          -- shubh/ashubh/mishrit
    rule_text TEXT NOT NULL,
    result_text TEXT NOT NULL,
    language VARCHAR(8) NOT NULL DEFAULT 'hi',
    updated_by_staff_id BIGINT UNSIGNED NULL,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    PRIMARY KEY (id), UNIQUE KEY uq_py (yoga_id, language), KEY idx_cat (category)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE yoga_hi=VALUES(yoga_hi), yoga_en=VALUES(yoga_en), category=VALUES(category),
    ref=VALUES(ref), yoga_type=VALUES(yoga_type), rule_text=VALUES(rule_text), result_text=VALUES(result_text);

ON DUPLICATE KEY UPDATE cfg_value=VALUES(cfg_value);
